    CONSTRAINT purchasing_purchaseorderitem_quantity_ordered_check CHECK ((quantity_ordered >= 0)),
    CONSTRAINT purchasing_purchaseorderitem_quantity_received_check CHECK ((quantity_received >= 0)),
    CONSTRAINT purchasing_purchaseorderitem_quantity_returned_check CHECK ((quantity_returned >= 0))
);


