INSERT INTO public.content_sitepage (id, created_at, updated_at, slug, title, meta_description, body, is_published, is_system, updated_by_id) VALUES ('61b57e62-1855-4765-abbd-451ee7502d4f', '2026-10-13 17:14:09.5613+00', '2026-10-13 17:14:09.561311+00', 'about', 'About Rangon Fashion', 'Rangon Fashion — clothing, shoes, bags and cosmetics, online and in Dhaka.', '<p>Rangon Fashion is a Dhaka retailer selling clothing, shoes, bags, cosmetics and accessories — from our store at Panthapath and online, with the same stock behind both.</p><p>When you buy something here, the same system that runs the till in the shop reserves it for you. That is why the availability you see is what is actually on the shelf, and why an item someone buys at the counter disappears from the website within seconds.</p><h2>What we sell</h2><p>Everyday menswear and womenswear, kidswear, footwear, bags and cosmetics — chosen for Dhaka’s climate and how people here actually dress, not for a catalogue photograph.</p><h2>Visit us</h2><p>Level 3, Bashundhara City, Panthapath, Dhaka 1215. Saturday to Thursday, 10:00–20:00.</p>', true, true, NULL);
INSERT INTO public.content_sitepage (id, created_at, updated_at, slug, title, meta_description, body, is_published, is_system, updated_by_id) VALUES ('a4427aa0-a5a6-4bb5-af9a-9218e7017bf0', '2026-10-13 17:14:09.563206+00', '2026-10-13 17:14:09.563217+00', 'contact', 'Contact us', 'Talk to Rangon Fashion — phone, email, or visit our Panthapath store in Dhaka.', '<p>Questions about an order, a size, or a return? We are happy to help.</p>', true, true, NULL);
INSERT INTO public.content_sitepage (id, created_at, updated_at, slug, title, meta_description, body, is_published, is_system, updated_by_id) VALUES ('1ced7d39-8715-4703-93e3-eec305d7f7b4', '2026-10-13 17:14:09.56459+00', '2026-10-13 17:14:09.564599+00', 'shipping', 'Shipping', 'Shipping policy for Rangon Fashion.', '<h2>Where we deliver</h2><p>We deliver across Bangladesh. Inside Dhaka usually takes 1–2 working days; outside Dhaka 2–5 working days.</p><p>You can also collect your order from our Panthapath store free of charge.</p><h2>Delivery charges</h2><p>Inside Dhaka: ৳70, free on orders over ৳3,000.</p><p>Outside Dhaka: ৳130, free on orders over ৳5,000.</p><p>The exact charge for your address is shown at checkout before you pay.</p><h2>Cash on delivery</h2><p>You can pay the courier when your order arrives. We will call the number on your order before delivery.</p>', true, true, NULL);
INSERT INTO public.content_sitepage (id, created_at, updated_at, slug, title, meta_description, body, is_published, is_system, updated_by_id) VALUES ('ab415936-093a-4675-9ce5-9752a33e9b07', '2026-10-13 17:14:09.565909+00', '2026-10-13 17:14:09.565917+00', 'returns', 'Returns & exchanges', 'Returns & exchanges policy for Rangon Fashion.', '<h2>Our return window</h2><p>You can return an item within 14 days of receiving it, as long as it is unworn, unwashed and in its original condition with the receipt.</p><p>Items marked final sale cannot be returned.</p><h2>How to return something</h2><p>Bring the item and your receipt to our store, or contact us to arrange a return for an online order.</p><p>Once we receive and check the item, we issue your refund to the method you originally paid with.</p><h2>Delivery charges on returns</h2><p>If the item was faulty, damaged, or not what you ordered, we refund the delivery charge too.</p><p>If you simply changed your mind, the delivery charge is not refunded.</p>', true, true, NULL);
INSERT INTO public.content_sitepage (id, created_at, updated_at, slug, title, meta_description, body, is_published, is_system, updated_by_id) VALUES ('7f364395-35d5-4ff7-9875-8cc9d9a48318', '2026-10-13 17:14:09.567166+00', '2026-10-13 17:14:09.567173+00', 'privacy', 'Privacy', 'Privacy policy for Rangon Fashion.', '<h2>What we collect</h2><p>Your name, phone number, delivery address and — if you give it — your email address. We keep a record of what you have ordered.</p><p>We do not store card numbers. Card payments are handled by the payment terminal or the payment provider.</p><h2>How we use it</h2><p>To take payment, deliver your order, handle returns, and keep the accounting records the law requires.</p><p>We do not sell your information.</p><h2>Your choices</h2><p>Contact us to see, correct or delete the personal information we hold. We keep financial records where we are legally required to, but we can anonymise your personal details.</p>', true, true, NULL);
INSERT INTO public.content_sitepage (id, created_at, updated_at, slug, title, meta_description, body, is_published, is_system, updated_by_id) VALUES ('19e0e886-2b15-43b0-97a9-e3b7d38ec571', '2026-10-13 17:14:09.568419+00', '2026-10-13 17:14:09.568451+00', 'terms', 'Terms', 'Terms of sale for Rangon Fashion.', '<h2>Orders</h2><p>Placing an order is an offer to buy. We confirm it once we have checked stock and your details.</p><p>Prices and availability shown on this site are confirmed by our system at checkout. If a price is wrong we will contact you before dispatching.</p><h2>Cancellation</h2><p>You can cancel an order before it is packed. After that, please use the returns process.</p>', true, true, NULL);


